#!/bin/bash
# Task B (Mac 1): install dnsmasq and serve the team's .test records.
source "$(dirname "$0")/../lib.sh"

say "Installing dnsmasq (skipped if already installed)"
brew list dnsmasq >/dev/null 2>&1 || brew install dnsmasq

CONF="$BREW_PREFIX/etc/dnsmasq.conf"
[ -f "$CONF" ] && [ ! -f "$CONF.orig" ] && cp "$CONF" "$CONF.orig"   # keep Homebrew's original
mkdir -p "$BREW_PREFIX/var/log"

say "Writing $CONF"
cat > "$CONF" <<EOF
# ---------------------------------------------------------------
# dnsmasq config for $DOMAIN  (generated by cn-project/dns/setup-dns.sh)
# ---------------------------------------------------------------

# Names that are NOT ours are forwarded upstream, so the other Macs' internet keeps working.
# Upstream = whatever DNS this Mac got from the Wi-Fi (read from /etc/resolv.conf; Mac 1's own
# DNS setting is never changed, so there is no loop), plus 8.8.8.8 as an extra.
resolv-file=/etc/resolv.conf
server=8.8.8.8
domain-needed
bogus-priv

# Our private zone: answer $DOMAIN ourselves, never forward it upstream
local=/$DOMAIN/

# --- Service records (clients only ever use these names) ---
host-record=app.$DOMAIN,$MAC2_IP
host-record=api.$DOMAIN,$MAC2_IP

# --- Infrastructure names (handy for the topology / inventory) ---
host-record=dns1.$DOMAIN,$MAC1_IP
host-record=edge.$DOMAIN,$MAC2_IP
host-record=backend-a.$DOMAIN,$MAC3_IP
host-record=backend-b.$DOMAIN,$MAC4_IP

# TTL (seconds): how long clients may cache our answers
local-ttl=30

# Log every query (evidence for the report)
log-queries
log-facility=$BREW_PREFIX/var/log/dnsmasq.log
EOF

say "Checking config syntax"
"$BREW_PREFIX/sbin/dnsmasq" --test --conf-file="$CONF" || exit 1

say "(Re)starting dnsmasq as root (needs port 53) — enter your Mac password if asked"
sudo brew services restart dnsmasq

# Mac 1 is also a test client. Use /etc/resolver so ONLY *.test lookups go to dnsmasq;
# all other internet DNS on this Mac stays exactly as it was.
if [ "$MY_IP" = "$MAC1_IP" ]; then
  say "Mac 1: sending *.$DOMAIN lookups to local dnsmasq via /etc/resolver/$DOMAIN"
  sudo mkdir -p /etc/resolver
  echo "nameserver 127.0.0.1" | sudo tee "/etc/resolver/$DOMAIN" >/dev/null
fi

sleep 1
say "Test: dig @127.0.0.1 app.$DOMAIN"
dig @127.0.0.1 "app.$DOMAIN" +noall +answer
dig @127.0.0.1 "api.$DOMAIN" +noall +answer
echo
echo "If you see two A records pointing to $MAC2_IP, DNS is working."
echo "Live query log:  tail -f $BREW_PREFIX/var/log/dnsmasq.log"
